"""Demo: prediction error is bounded by wrongness (Cauchy-Schwarz)."""
from __future__ import annotations
import math, random
from typing import Sequence, List

def inner(x: Sequence[float], y: Sequence[float]) -> float:
    return sum(a * b for a, b in zip(x, y))

def norm(x: Sequence[float]) -> float:
    return math.sqrt(inner(x, x))

def sub(x: Sequence[float], y: Sequence[float]) -> List[float]:
    return [a - b for a, b in zip(x, y)]

def wrongness(truth: Sequence[float], theory: Sequence[float]) -> float:
    return norm(sub(theory, truth))

def pred_err(truth: Sequence[float], theory: Sequence[float],
             u: Sequence[float]) -> float:
    return abs(inner(sub(theory, truth), u))

def main() -> None:
    rng = random.Random(1)
    d = 5
    truth = [rng.uniform(-1, 1) for _ in range(d)]
    for _ in range(8):
        theory = [rng.uniform(-3, 3) for _ in range(d)]
        u = [rng.uniform(-2, 2) for _ in range(d)]
        pe = pred_err(truth, theory, u)
        bound = wrongness(truth, theory) * norm(u)
        print(f"predErr={pe:8.4f}  bound={bound:8.4f}  holds={pe <= bound + 1e-9}")

if __name__ == "__main__":
    main()

"""Demo: a single phenomenon on which a wrong theory beats a finite field of rivals."""
from __future__ import annotations
import math, random
from typing import Sequence, List

def inner(x, y): return sum(a * b for a, b in zip(x, y))
def norm(x): return math.sqrt(inner(x, x))
def sub(x, y): return [a - b for a, b in zip(x, y)]
def add(x, y): return [a + b for a, b in zip(x, y)]
def smul(t, x): return [t * a for a in x]

def orth_residue(truth, a_theory, b_theory) -> List[float]:
    a = sub(a_theory, truth); b = sub(b_theory, truth)
    return sub(b, smul(inner(b, a) / inner(a, a), a))

def common_non_annihilating(vectors: List[List[float]]) -> List[float]:
    if not vectors:
        return []
    u = [0.0] * len(vectors[0])
    rng = random.Random(0)
    for k, q in enumerate(vectors):
        for _ in range(1000):
            t = rng.uniform(0.5, 5.0)
            cand = add(u, smul(t, q))
            if all(abs(inner(v, cand)) > 1e-9 for v in vectors[:k + 1]):
                u = cand
                break
    return u

def pred_err(truth, theory, u): return abs(inner(sub(theory, truth), u))

def main() -> None:
    rng = random.Random(4)
    d = 6
    truth = [rng.uniform(-1, 1) for _ in range(d)]
    a_theory = [rng.uniform(-2, 2) for _ in range(d)]
    rivals = [[rng.uniform(-2, 2) for _ in range(d)] for _ in range(5)]
    u = common_non_annihilating([orth_residue(truth, a_theory, b) for b in rivals])
    print(f"predErr(A, u) = {pred_err(truth, a_theory, u):.3e}")
    for j, b in enumerate(rivals):
        print(f"predErr(B_{j+1}, u) = {pred_err(truth, b, u):.6f}")

if __name__ == "__main__":
    main()

