from __future__ import annotations
import math
from typing import Sequence, List

def inner(x: Sequence[float], y: Sequence[float]) -> float:
    return sum(a * b for a, b in zip(x, y))

def sub(x: Sequence[float], y: Sequence[float]) -> List[float]:
    return [a - b for a, b in zip(x, y)]

def smul(t: float, x: Sequence[float]) -> List[float]:
    return [t * a for a in x]

def winning_phenomenon_single(truth: Sequence[float],
                              a_theory: Sequence[float],
                              b_theory: Sequence[float]) -> List[float]:
    """Return the phenomenon q on which wrong theory A is exact and rival B
    errs by ||q||^2. q is the Gram-Schmidt residue of B's error against A's."""
    a = sub(a_theory, truth)
    b = sub(b_theory, truth)
    coeff = inner(b, a) / inner(a, a)
    return sub(b, smul(coeff, a))

