import random
from typing import Sequence, List

def inner(x: Sequence[float], y: Sequence[float]) -> float:
    return sum(a * b for a, b in zip(x, y))

def add(x: Sequence[float], y: Sequence[float]) -> List[float]:
    return [a + b for a, b in zip(x, y)]

def smul(t: float, x: Sequence[float]) -> List[float]:
    return [t * a for a in x]

def hyperplane_avoiding_vector(vectors: List[List[float]],
                               tol: float = 1e-9) -> List[float]:
    """Build a single u with <q, u> != 0 for every nonzero q in `vectors`.
    Incremental: u <- u + t*q with t avoiding the finite forbidden set."""
    if not vectors:
        return []
    u = [0.0] * len(vectors[0])
    rng = random.Random(0)
    for k, q in enumerate(vectors):
        for _ in range(10000):
            t = rng.uniform(0.5, 5.0)
            cand = add(u, smul(t, q))
            if all(abs(inner(v, cand)) > tol for v in vectors[:k + 1]):
                u = cand
                break
        else:
            raise RuntimeError("failed to avoid forbidden set")
    return u

